"""Reversible batches and list imports (R107 increments 0 and 1, design/bulk-import.md §8a, §9).

Five new tables, moving no stored row, and an index on each hierarchy list's ``path``: ``batches`` and ``batch_effects`` (the shared batch ledger, which bank feeds and
grid edits reuse), ``import_runs``, ``import_rows`` and ``import_keys``. Guards: effects and row outcomes are immutable;
nothing here is ever deleted; a batch changes only its state and reversal columns (and never once reversed), a run only
its state, a key only its release, once. DDL below is frozen: this migration never imports current application metadata.
"""
from alembic import op

revision = 'co0105'
down_revision = 'co0104'
branch_labels = depends_on = None

DDL = ("\nCREATE TABLE batches (\n\tid VARCHAR(26) NOT NULL, \n\tkind VARCHAR(32) NOT NULL, \n\tscope VARCHAR(200) NOT NULL, \n\tordering VARCHAR(8) NOT NULL, \n\tlabel VARCHAR(200) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tsource_type VARCHAR(32), \n\tsource_id VARCHAR(26), \n\treversal_of VARCHAR(26), \n\tactor_id VARCHAR(26) NOT NULL, \n\tactor_kind VARCHAR(16), \n\tvia VARCHAR(16) NOT NULL, \n\ton_behalf_of VARCHAR(26), \n\treason TEXT, \n\tcreated_at VARCHAR(32) NOT NULL, \n\treversed_by VARCHAR(26), \n\treversed_at VARCHAR(32), \n\treversal_reason TEXT, \n\treversal_event_id VARCHAR(26), \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_batch_state CHECK (state IN ('live', 'reversing', 'blocked', 'reversed', 'reversed_partly')), \n\tCONSTRAINT ck_batch_ordering CHECK (ordering IN ('strict', 'record')), \n\tFOREIGN KEY(reversal_of) REFERENCES batches (id), \n\tFOREIGN KEY(reversed_by) REFERENCES batches (id), \n\tFOREIGN KEY(reversal_event_id) REFERENCES audit_events (id)\n)\n\n", '\nCREATE TABLE batch_effects (\n\tbatch_id VARCHAR(26) NOT NULL, \n\tseq INTEGER NOT NULL, \n\trecord_type VARCHAR(64) NOT NULL, \n\trecord_id VARCHAR(26) NOT NULL, \n\taction VARCHAR(16) NOT NULL, \n\tversion_after INTEGER, \n\t"before" TEXT, \n\tevent_id VARCHAR(26), \n\tcreated_at VARCHAR(32) NOT NULL, \n\tPRIMARY KEY (batch_id, seq), \n\tCONSTRAINT ck_batch_effect_action CHECK (action IN (\'created\', \'updated\', \'linked\', \'rule_learned\', \'reversed\')), \n\tCONSTRAINT ck_batch_effect_seq CHECK (seq > 0), \n\tFOREIGN KEY(batch_id) REFERENCES batches (id), \n\tFOREIGN KEY(event_id) REFERENCES audit_events (id)\n)\n\n', "\nCREATE TABLE import_runs (\n\tid VARCHAR(26) NOT NULL, \n\tkind VARCHAR(32) NOT NULL, \n\tmode VARCHAR(8) NOT NULL, \n\tatomic BOOLEAN NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tsource VARCHAR(200) NOT NULL, \n\tmapping TEXT NOT NULL, \n\tattachment_id VARCHAR(26), \n\tfile_name VARCHAR(255), \n\tfile_sha256 VARCHAR(64) NOT NULL, \n\tencoding VARCHAR(32) NOT NULL, \n\tdelimiter VARCHAR(8) NOT NULL, \n\trow_count INTEGER NOT NULL, \n\tstop_after_refusals INTEGER NOT NULL, \n\tbatch_id VARCHAR(26), \n\treason TEXT, \n\tversion INTEGER NOT NULL, \n\tcreated_at VARCHAR(32) NOT NULL, \n\tcreated_by VARCHAR(26) NOT NULL, \n\tcreated_via VARCHAR(16) NOT NULL, \n\tupdated_at VARCHAR(32) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_import_run_state CHECK (state IN ('previewed', 'running', 'stopped', 'waiting', 'done', 'cancelled', 'rolled_back', 'failed')), \n\tCONSTRAINT ck_import_run_mode CHECK (mode IN ('create', 'update', 'upsert')), \n\tFOREIGN KEY(batch_id) REFERENCES batches (id)\n)\n\n", "\nCREATE TABLE import_rows (\n\trun_id VARCHAR(26) NOT NULL, \n\trow_no INTEGER NOT NULL, \n\tphase VARCHAR(8) NOT NULL, \n\tline INTEGER NOT NULL, \n\tkey_hash VARCHAR(64), \n\tstatus VARCHAR(16) NOT NULL, \n\tcode VARCHAR(64), \n\tmessage TEXT, \n\tcolumn_name VARCHAR(200), \n\trecord_type VARCHAR(64), \n\trecord_id VARCHAR(26), \n\tpayload TEXT, \n\tcells TEXT, \n\tcreated_at VARCHAR(32) NOT NULL, \n\tPRIMARY KEY (run_id, row_no, phase), \n\tCONSTRAINT ck_import_row_phase CHECK (phase IN ('preview', 'run')), \n\tFOREIGN KEY(run_id) REFERENCES import_runs (id)\n)\n\n", '\nCREATE TABLE import_keys (\n\tid VARCHAR(26) NOT NULL, \n\tsource VARCHAR(200) NOT NULL, \n\tkey_hash VARCHAR(64) NOT NULL, \n\trecord_type VARCHAR(64) NOT NULL, \n\trecord_id VARCHAR(26) NOT NULL, \n\trun_id VARCHAR(26) NOT NULL, \n\tbatch_id VARCHAR(26) NOT NULL, \n\tcreated_at VARCHAR(32) NOT NULL, \n\treleased_by VARCHAR(26), \n\treleased_at VARCHAR(32), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(run_id) REFERENCES import_runs (id), \n\tFOREIGN KEY(batch_id) REFERENCES batches (id), \n\tFOREIGN KEY(released_by) REFERENCES batches (id)\n)\n\n')
INDEXES = ('CREATE INDEX ix_batches_scope ON batches (scope, created_at)', 'CREATE INDEX ix_batch_effects_record ON batch_effects (record_type, record_id)', 'CREATE INDEX ix_import_keys_batch ON import_keys (batch_id)', 'CREATE INDEX ix_import_keys_record ON import_keys (record_type, record_id)', 'CREATE UNIQUE INDEX ux_import_keys_standing ON import_keys (source, key_hash) WHERE released_by IS NULL')
GUARDS = ("CREATE TRIGGER batch_effects_immutable_update BEFORE UPDATE ON batch_effects BEGIN SELECT RAISE(ABORT, 'immutable batch effects'); END", "CREATE TRIGGER import_rows_immutable_update BEFORE UPDATE ON import_rows BEGIN SELECT RAISE(ABORT, 'immutable import rows'); END", "CREATE TRIGGER batches_no_delete BEFORE DELETE ON batches BEGIN SELECT RAISE(ABORT, 'immutable batches'); END", "CREATE TRIGGER batch_effects_no_delete BEFORE DELETE ON batch_effects BEGIN SELECT RAISE(ABORT, 'immutable batch effects'); END", "CREATE TRIGGER import_runs_no_delete BEFORE DELETE ON import_runs BEGIN SELECT RAISE(ABORT, 'immutable import runs'); END", "CREATE TRIGGER import_rows_no_delete BEFORE DELETE ON import_rows BEGIN SELECT RAISE(ABORT, 'immutable import rows'); END", "CREATE TRIGGER import_keys_no_delete BEFORE DELETE ON import_keys BEGIN SELECT RAISE(ABORT, 'immutable import keys'); END", "CREATE TRIGGER batches_frozen BEFORE UPDATE ON batches WHEN OLD.state = 'reversed' OR NEW.id IS NOT OLD.id OR NEW.kind IS NOT OLD.kind OR NEW.scope IS NOT OLD.scope OR NEW.ordering IS NOT OLD.ordering OR NEW.label IS NOT OLD.label OR NEW.source_type IS NOT OLD.source_type OR NEW.source_id IS NOT OLD.source_id OR NEW.reversal_of IS NOT OLD.reversal_of OR NEW.actor_id IS NOT OLD.actor_id OR NEW.actor_kind IS NOT OLD.actor_kind OR NEW.via IS NOT OLD.via OR NEW.on_behalf_of IS NOT OLD.on_behalf_of OR NEW.reason IS NOT OLD.reason OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT, 'a batch changes only its state and reversal'); END", "CREATE TRIGGER import_runs_frozen BEFORE UPDATE ON import_runs WHEN NEW.id IS NOT OLD.id OR NEW.kind IS NOT OLD.kind OR NEW.mode IS NOT OLD.mode OR NEW.atomic IS NOT OLD.atomic OR NEW.source IS NOT OLD.source OR NEW.mapping IS NOT OLD.mapping OR NEW.attachment_id IS NOT OLD.attachment_id OR NEW.file_name IS NOT OLD.file_name OR NEW.file_sha256 IS NOT OLD.file_sha256 OR NEW.encoding IS NOT OLD.encoding OR NEW.delimiter IS NOT OLD.delimiter OR NEW.row_count IS NOT OLD.row_count OR NEW.stop_after_refusals IS NOT OLD.stop_after_refusals OR NEW.reason IS NOT OLD.reason OR NEW.created_at IS NOT OLD.created_at OR NEW.created_by IS NOT OLD.created_by OR NEW.created_via IS NOT OLD.created_via BEGIN SELECT RAISE(ABORT, 'an import run changes only its state'); END", "CREATE TRIGGER import_keys_release_once BEFORE UPDATE ON import_keys WHEN OLD.released_by IS NOT NULL OR NEW.released_by IS NULL OR NEW.id IS NOT OLD.id OR NEW.source IS NOT OLD.source OR NEW.key_hash IS NOT OLD.key_hash OR NEW.record_type IS NOT OLD.record_type OR NEW.record_id IS NOT OLD.record_id OR NEW.run_id IS NOT OLD.run_id OR NEW.batch_id IS NOT OLD.batch_id OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT, 'an import key is only released, once'); END")
# The hierarchy lists' paths, indexed so a subtree is a range read (list_service._hierarchy_rows), not a scan.
PATH_INDEXES = tuple(f'CREATE INDEX ix_{table}_path ON {table} (path)' for table in (
    'accounts', 'items', 'item_categories', 'classes', 'customer_types', 'vendor_types', 'job_types', 'customers'))
TABLES = ('import_keys', 'import_rows', 'import_runs', 'batch_effects', 'batches')
# What a test rewinding a head file drops: the guards, then the tables (children first).
TRIGGERS = tuple(statement.split()[2] for statement in GUARDS)


def upgrade():
    connection = op.get_bind()
    reserved = set(TABLES) | set(TRIGGERS) | {statement.split()[2] for statement in PATH_INDEXES}
    existing = {name.casefold() for name in connection.exec_driver_sql('SELECT name FROM sqlite_schema').scalars().all()}
    if {name.casefold() for name in reserved} & existing:
        raise RuntimeError('co0105 reserved object already exists')
    for statement in DDL + INDEXES + PATH_INDEXES + GUARDS:
        connection.exec_driver_sql(statement)


def downgrade():
    raise RuntimeError('Company migrations are forward-only')
